// Extract and optimize script for voice generation
const scriptContent = $('Script Generator').item.json.choices[0].message.content;

// Clean script for TTS - remove markdown, stage directions
const cleanScript = scriptContent
  .replace(/\*\*([^*]+)\*\*/g, '$1') // Remove bold
  .replace(/\*([^*]+)\*/g, '$1') // Remove italics
  .replace(/\[.*?\]/g, '') // Remove stage directions
  .replace(/\n\n+/g, '\n') // Clean multiple line breaks
  .trim();

// Extract title suggestions from script or create from topic
const topic = $('Smart Topic Selector').item.json.selectedTopic;
const contentType = $('Smart Topic Selector').item.json.contentType;

// Generate clickbait title variations
const titleVariations = [
  `${topic} (You Won't Believe This!)`,
  `The Truth About ${topic}`,
  `Why Everyone Is Wrong About ${topic}`,
  `${topic} - This Changes Everything`,
  `I Tested ${topic} For 30 Days (Results Shocking)`
];

const selectedTitle = titleVariations[Math.floor(Math.random() * titleVariations.length)];

return {
  cleanScript: cleanScript,
  originalScript: scriptContent,
  selectedTitle: selectedTitle,
  contentType: contentType,
  timestamp: new Date().toISOString()
};

// Create optimized thumbnail prompt for short-form content
const title = $('Script Processor').item.json.selectedTitle;
const contentType = $('Script Processor').item.json.contentType;
const topic = $('Smart Topic Selector').item.json.selectedTopic;

// Thumbnail style based on content type
const thumbnailStyle = contentType === 'short' ? 
  'YouTube Shorts thumbnail: Vertical 9:16 format, mobile-optimized' : 
  'YouTube thumbnail: 16:9 format, desktop and mobile optimized';

const thumbnailPrompt = `${thumbnailStyle}. Title: "${title}". 
Style requirements:
- Bold, readable text overlay (max 6 words)
- Shocked/surprised facial expression or reaction
- High contrast colors (red, yellow, white text)
- Professional quality but attention-grabbing
- Clean background, focus on main subject
- Emotion-triggering visual elements
- No copyright content
- Optimized for small screens`;

// Generate description with hashtags
const description = `${topic}\n\n🔥 TIMESTAMPS:\n0:00 - Hook\n0:03 - The Problem\n0:30 - Solutions\n${contentType === 'short' ? '0:50' : '3:30'} - Call to Action\n\n💡 What did you think? Comment below!\n\n${$('Smart Topic Selector').item.json.hashtags}`;

return {
  thumbnailPrompt,
  selectedTitle: title,
  description,
  contentType,
  timestamp: new Date().toISOString()
};

// Create video generation prompt optimized for short content
const topic = $('Smart Topic Selector').item.json.selectedTopic;
const duration = $('Smart Topic Selector').item.json.targetDuration;
const contentType = $('Smart Topic Selector').item.json.contentType;
const script = $('Script Processor').item.json.originalScript;

// Video style based on content type
const videoStyle = contentType === 'short' ? 
  'Vertical 9:16 format, fast-paced cuts every 2-3 seconds, mobile-first design' : 
  'Horizontal 16:9 format, dynamic cuts every 3-5 seconds, engaging visuals';

const videoPrompt = `Create ${duration}-second video about: ${topic}

Video requirements:
- ${videoStyle}
- Hook viewers in first 3 seconds
- Stock footage + motion graphics
- Text overlays for key points
- Smooth transitions
- High retention editing style
- Professional but engaging tone
- No talking heads, focus on visuals
- Fast-paced to maintain attention

Script context: ${script.substring(0, 200)}...`;

return {
  videoPrompt,
  duration,
  contentType,
  aspectRatio: contentType === 'short' ? '9:16' : '16:9',
  timestamp: new Date().toISOString()
};

// Optimized video processing for short content
const contentType = $('Content Optimizer').item.json.contentType;
const videoUrl = $('Fast Video Gen').item.json.output_url;
const audioData = $('AI Voice Generation').item.binary.data;

// FFmpeg optimization for different content types
const ffmpegCommand = {
  inputs: [
    { path: videoUrl },
    { path: audioData }
  ],
  output: `${contentType}_video_${Date.now()}.mp4`,
  options: contentType === 'short' ? [
    // YouTube Shorts optimization
    '-c:v libx264',
    '-preset fast',
    '-crf 23',
    '-c:a aac',
    '-b:a 128k',
    '-ar 44100',
    '-vf "scale=1080:1920:force_original_aspect_ratio=decrease,pad=1080:1920:(ow-iw)/2:(oh-ih)/2"',
    '-r 30',
    '-map 0:v:0',
    '-map 1:a:0',
    '-shortest',
    '-movflags +faststart'
  ] : [
    // Regular video optimization
    '-c:v libx264',
    '-preset fast',
    '-crf 21',
    '-c:a aac',
    '-b:a 192k',
    '-ar 44100',
    '-vf "scale=1920:1080:force_original_aspect_ratio=decrease,pad=1920:1080:(ow-iw)/2:(oh-ih)/2"',
    '-r 30',
    '-map 0:v:0',
    '-map 1:a:0',
    '-shortest',
    '-movflags +faststart'
  ]
};

return {
  ffmpegCommand,
  videoReady: true,
  contentType,
  outputFile: `${contentType}_video_${Date.now()}.mp4`,
  timestamp: new Date().toISOString()
};

// Analytics and success metrics
const uploadResult = $('Auto Upload').item.json;
const contentType = $('Smart Processing').item.json.contentType;
const topic = $('Smart Topic Selector').item.json.selectedTopic;

const completionReport = {
  status: 'SUCCESS',
  contentType: contentType,
  topic: topic,
  videoId: uploadResult.id,
  title: $('Content Optimizer').item.json.selectedTitle,
  uploadTime: new Date().toISOString(),
  videoUrl: `https://youtube.com/watch?v=${uploadResult.id}`,
  optimizations: [
    'Smart topic selection',
    'Competitor research',
    'Trend validation',
    'AI script generation',
    'Voice synthesis',
    'Auto thumbnail',
    'Format optimization',
    'SEO metadata'
  ]
};

console.log('=== UPLOAD COMPLETE ===');
console.log(JSON.stringify(completionReport, null, 2));

return completionReport;
